"""Runtime for indicator plugins generated by tools.pine2py (standard library only).

Generated code runs a Pine script the way TradingView does: once per bar, oldest first. This
module supplies what that needs:

- ``na``: Pine's "no value". Arithmetic with na gives na, every comparison with na is false,
  and na is falsy, so ``if`` and ``?:`` treat it like Pine. ``nz()`` and ``isna()`` (Pine's
  ``na(x)``) test and replace it. It becomes ``None`` only when points are handed to the chart.
- ``Series``: a variable's history, so ``x[1]`` is the value one bar (one execution) ago and
  anything out of range is na.
- ``Context``: the candles, the current bar and the built-in series (``close[1]``...).
- ``State``: per call-site state. Every ``ta.*`` call (and every user function call) in the
  script gets its own State, exactly like Pine, so two ``ta.sma(close, 20)`` calls never share
  history. ``state.sub(key)`` gives nested call sites their own children.
- ``ta_*`` / ``math_*`` / ``color_*`` built-ins, implemented incrementally (one bar per call).
- ``Output``: collects what the script plots and returns the plugin ``{"series": [...]}``.

Everything here draws lines with the user's parameters; nothing is a signal.
"""

from __future__ import annotations

import math
import statistics
from datetime import datetime, timezone

SESSION_START_UTC = 22 * 3600      # ta.vwap resets at 22:00 UTC, like the dashboard's VWAP
MAX_LOOP = 1_000_000               # iterations one loop may run on one bar before it is stopped
DEFAULT_TICK = 0.25


# -- na ---------------------------------------------------------------------------------------


class NaType:
    """Pine's na: propagates through arithmetic, compares false, is falsy."""

    __slots__ = ()
    _instance = None

    def __new__(cls):
        if cls._instance is None:
            cls._instance = super().__new__(cls)
        return cls._instance

    def __repr__(self) -> str:
        return "na"

    __str__ = __repr__

    def __bool__(self) -> bool:
        return False

    def _na(self, *args):
        return self

    __add__ = __radd__ = __sub__ = __rsub__ = __mul__ = __rmul__ = _na
    __truediv__ = __rtruediv__ = __floordiv__ = __rfloordiv__ = __mod__ = __rmod__ = _na
    __pow__ = __rpow__ = __neg__ = __pos__ = __abs__ = __round__ = _na

    def _false(self, other) -> bool:
        return False

    __lt__ = __le__ = __gt__ = __ge__ = __eq__ = __ne__ = _false

    def __hash__(self) -> int:
        return 0x9A9A

    def __float__(self) -> float:
        return math.nan

    def __reduce__(self):
        return (NaType, ())


na = NA = NaType()


class _Unset:
    __slots__ = ()

    def __repr__(self) -> str:
        return "UNSET"

    def __bool__(self) -> bool:
        return False


UNSET = _Unset()   # a ``var`` that has not been initialised yet


def isna(x) -> bool:
    """Pine ``na(x)``: true for na, None and NaN."""
    return x is na or x is None or (x.__class__ is float and x != x)


def nz(x, replacement=0):
    """Pine ``nz(x, replacement)``: x, or the replacement when x is na."""
    return replacement if isna(x) else x


def _clean(x):
    return na if isna(x) else x


def div(a, b):
    """``a / b`` with Pine's rules: na in, na out; dividing by zero gives na."""
    try:
        return a / b
    except (ZeroDivisionError, TypeError, OverflowError):
        return na


def mod(a, b):
    """``a % b`` (remainder with the sign of a, like Pine); na or a zero divisor gives na."""
    if isna(a) or isna(b) or b == 0:
        return na
    try:
        r = math.fmod(a, b)
    except (TypeError, ValueError):
        return na
    return int(r) if isinstance(a, int) and isinstance(b, int) else r


def not_(x):
    """Pine ``not x``; ``not na`` stays na (falsy)."""
    return na if isna(x) else (not x)


def _offset(n) -> int | None:
    """A history offset: a whole number >= 0, or None."""
    if isna(n):
        return None
    try:
        k = int(n)
    except (TypeError, ValueError, OverflowError):
        return None
    return k if k >= 0 else None


def _length(n) -> int:
    """A ta.* length: a whole number >= 1, or 0 when it is not usable."""
    if isna(n):
        return 0
    try:
        k = int(n)
    except (TypeError, ValueError, OverflowError):
        return 0
    return k if k >= 1 else 0


# -- series ------------------------------------------------------------------------------------


class Series:
    """The history of one variable (or expression) at one place in the script.

    ``push(v)`` opens a new slot each time the declaration runs (once per bar at the top level,
    once per execution inside a block or function); ``set(v)`` updates the current slot after a
    ``:=``; ``s[n]`` is the value n slots back (``s[0]`` is the current one), na out of range.
    """

    __slots__ = ("values",)

    def __init__(self):
        self.values = []

    def push(self, value):
        self.values.append(value)
        return self

    def set(self, value):
        if self.values:
            self.values[-1] = value
        else:
            self.values.append(value)
        return value

    def __getitem__(self, n):
        k = _offset(n)
        if k is None:
            return na
        i = len(self.values) - 1 - k
        return self.values[i] if i >= 0 else na

    def __len__(self) -> int:
        return len(self.values)


class _Column:
    """A built-in series (close, high, bar_index, ...) indexed relative to the current bar."""

    __slots__ = ("ctx", "values")

    def __init__(self, ctx, values):
        self.ctx = ctx
        self.values = values

    def __getitem__(self, n):
        k = _offset(n)
        if k is None:
            return na
        i = self.ctx.index - k
        return self.values[i] if i >= 0 else na


class Vars:
    """``var`` variables of one function call site: ``v.x``; ``"x" in v`` once initialised."""

    def __contains__(self, name: str) -> bool:
        return name in self.__dict__


class State:
    """Per call-site state. ta.* functions keep their history as attributes on it."""

    def __init__(self, ctx):
        self.ctx = ctx
        self._kids = {}
        self._series = {}
        self._vars = None

    def sub(self, key) -> "State":
        kid = self._kids.get(key)
        if kid is None:
            kid = self._kids[key] = State(self.ctx)
        return kid

    def series(self, key) -> Series:
        s = self._series.get(key)
        if s is None:
            s = self._series[key] = Series()
        return s

    @property
    def vars(self) -> Vars:
        if self._vars is None:
            self._vars = Vars()
        return self._vars


class LoopGuard:
    """Stops a runaway ``while`` loop (Pine stops long loops too)."""

    __slots__ = ("count", "line")

    def __init__(self, line: int):
        self.count = 0
        self.line = line

    def tick(self) -> None:
        self.count += 1
        if self.count > MAX_LOOP:
            raise RuntimeError(f"the while loop at Pine line {self.line} ran more than {MAX_LOOP} times on one bar")


def loop_range(start, end, step=None):
    """Pine ``for i = start to end [by step]``: inclusive, counts down when end < start."""
    if isna(start) or isna(end) or (step is not None and isna(step)):
        return ()
    direction = 1 if end >= start else -1
    size = abs(step) if step is not None else 1
    if size == 0:
        return ()
    if all(isinstance(v, int) for v in (start, end, size)):
        count = abs(end - start) // size + 1
        if count > MAX_LOOP:
            raise RuntimeError(f"a for loop would run {count} times on one bar (limit {MAX_LOOP})")
        return range(start, end + direction, direction * size)
    return _float_range(start, end, direction * size)


def _float_range(start, end, step):
    value, count = start, 0
    while (value <= end + 1e-12) if step > 0 else (value >= end - 1e-12):
        yield value
        value += step
        count += 1
        if count > MAX_LOOP:
            raise RuntimeError(f"a for loop ran more than {MAX_LOOP} times on one bar")


# -- candles and the current bar ---------------------------------------------------------------


def _number(value) -> float | None:
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        try:
            value = float(value)
        except (TypeError, ValueError):
            return None
    value = float(value)
    return value if math.isfinite(value) else None


class Bar:
    __slots__ = ("index", "time", "open", "high", "low", "close", "volume", "hl2", "hlc3", "ohlc4", "hlcc4",
                 "isfirst", "islast")


class Context:
    """The candles of one compute() call and the bar the script is on."""

    def __init__(self, candles, params=None):
        params = params or {}
        times, opens, highs, lows, closes, volumes = [], [], [], [], [], []
        for c in candles or []:
            if not isinstance(c, dict):
                continue
            try:
                t = int(c["time"])
            except (KeyError, TypeError, ValueError):
                continue
            o, h, l, cl = (_number(c.get(k)) for k in ("open", "high", "low", "close"))
            if None in (o, h, l, cl):
                continue    # a candle without prices cannot be drawn either
            v = _number(c.get("volume"))
            times.append(t)
            opens.append(o)
            highs.append(h)
            lows.append(l)
            closes.append(cl)
            volumes.append(v if v is not None else 0.0)
        self.times = times                       # UTC seconds (chart times)
        self.opens, self.highs, self.lows, self.closes, self.volumes = opens, highs, lows, closes, volumes
        self.hl2s = [(h + l) / 2 for h, l in zip(highs, lows)]
        self.hlc3s = [(h + l + c) / 3 for h, l, c in zip(highs, lows, closes)]
        self.ohlc4s = [(o + h + l + c) / 4 for o, h, l, c in zip(opens, highs, lows, closes)]
        self.hlcc4s = [(h + l + c + c) / 4 for h, l, c in zip(highs, lows, closes)]
        self.size = len(times)
        self.index = -1
        self.last_bar_index = self.size - 1
        self.open, self.high, self.low = _Column(self, opens), _Column(self, highs), _Column(self, lows)
        self.close, self.volume = _Column(self, closes), _Column(self, volumes)
        self.hl2, self.hlc3 = _Column(self, self.hl2s), _Column(self, self.hlc3s)
        self.ohlc4, self.hlcc4 = _Column(self, self.ohlc4s), _Column(self, self.hlcc4s)
        self.time = _Column(self, [t * 1000 for t in times])     # Pine time is in milliseconds
        self.bar_index = _Column(self, range(self.size))
        tick = _number(params.get("tick_size"))
        self.mintick = tick if tick is not None and tick > 0 else DEFAULT_TICK
        gaps = sorted(b - a for a, b in zip(times, times[1:]) if b > a)
        self.bar_seconds = gaps[len(gaps) // 2] if gaps else 60

    def state(self) -> State:
        return State(self)

    def source(self, name) -> _Column:
        """The built-in series an ``input.source`` parameter names (close when unknown)."""
        return {
            "open": self.open, "high": self.high, "low": self.low, "close": self.close, "volume": self.volume,
            "hl2": self.hl2, "hlc3": self.hlc3, "ohlc4": self.ohlc4, "hlcc4": self.hlcc4,
        }.get(str(name), self.close)

    def bars(self):
        last = self.size - 1
        for i in range(self.size):
            self.index = i
            bar = Bar()
            bar.index = i
            bar.time = self.times[i] * 1000
            bar.open, bar.high, bar.low = self.opens[i], self.highs[i], self.lows[i]
            bar.close, bar.volume = self.closes[i], self.volumes[i]
            bar.hl2, bar.hlc3, bar.ohlc4, bar.hlcc4 = self.hl2s[i], self.hlc3s[i], self.ohlc4s[i], self.hlcc4s[i]
            bar.isfirst = i == 0
            bar.islast = i == last
            yield bar

    # timeframe.* derived from the candle spacing (the dashboard has no symbol settings)
    def timeframe_period(self) -> str:
        s = self.bar_seconds
        if s % 86400 == 0:
            days = s // 86400
            if days % 7 == 0:
                return f"{days // 7}W" if days // 7 > 1 else "W"
            return f"{days}D" if days > 1 else "D"
        if s % 60 == 0:
            return str(s // 60)
        return f"{s}S"

    def timeframe_multiplier(self) -> int:
        s = self.bar_seconds
        if s % 86400 == 0:
            days = s // 86400
            return days // 7 if days % 7 == 0 else days
        return s // 60 if s % 60 == 0 else s


def time_part(ms, part: str):
    """year/month/dayofmonth/dayofweek/hour/minute/second/weekofyear of a Pine time (ms, UTC)."""
    if isna(ms):
        return na
    dt = datetime.fromtimestamp(ms / 1000, tz=timezone.utc)
    if part == "dayofweek":
        return (dt.weekday() + 1) % 7 + 1      # Pine: 1 = Sunday ... 7 = Saturday
    if part == "weekofyear":
        return dt.isocalendar()[1]
    if part == "dayofmonth":
        return dt.day
    return getattr(dt, part)


# -- conversions and strings ---------------------------------------------------------------------


def to_int(x):
    if isna(x):
        return na
    try:
        return int(x)
    except (TypeError, ValueError, OverflowError):
        return na


def to_float(x):
    if isna(x):
        return na
    try:
        return float(x)
    except (TypeError, ValueError):
        return na


def to_bool(x) -> bool:
    return bool(x) and not isna(x)


def str_tostring(value, fmt=None) -> str:
    if isna(value):
        return "NaN"
    if isinstance(value, bool):
        return "true" if value else "false"
    if isinstance(value, str):
        return value
    if isinstance(fmt, str) and fmt:
        if fmt == "percent":
            return f"{value:.2f}%"
        if "." in fmt:
            decimals = fmt.split(".", 1)[1]
            places = len(decimals)
            text = f"{value:.{places}f}"
            if set(decimals) == {"#"}:
                text = text.rstrip("0").rstrip(".")
            return text
        if set(fmt) <= {"#", "0"}:
            return str(int(round(value)))
    if isinstance(value, int) or float(value).is_integer() and abs(value) < 1e15:
        return str(int(value))
    return f"{value:.10f}".rstrip("0").rstrip(".")


def str_length(s):
    return na if isna(s) else len(str(s))


def str_upper(s):
    return na if isna(s) else str(s).upper()


def str_lower(s):
    return na if isna(s) else str(s).lower()


def str_contains(s, part) -> bool:
    return not isna(s) and not isna(part) and str(part) in str(s)


def str_startswith(s, part) -> bool:
    return not isna(s) and not isna(part) and str(s).startswith(str(part))


def str_endswith(s, part) -> bool:
    return not isna(s) and not isna(part) and str(s).endswith(str(part))


def str_replace_all(s, target, replacement):
    return na if isna(s) else str(s).replace(str(target), str(replacement))


def str_format(fmt, *args) -> str:
    text = str(fmt)
    for i, arg in enumerate(args):
        text = text.replace("{" + str(i) + "}", str_tostring(arg))
    return text


# -- colors --------------------------------------------------------------------------------------


def _rgba(color):
    if not isinstance(color, str) or not color.startswith("#") or len(color) not in (7, 9):
        return None
    try:
        r, g, b = int(color[1:3], 16), int(color[3:5], 16), int(color[5:7], 16)
        a = int(color[7:9], 16) if len(color) == 9 else 255
    except ValueError:
        return None
    return r, g, b, a


def _hex(r, g, b, a=255) -> str:
    r, g, b, a = (max(0, min(255, int(round(v)))) for v in (r, g, b, a))
    return f"#{r:02x}{g:02x}{b:02x}" + ("" if a == 255 else f"{a:02x}")


def color_new(color, transp=0):
    """Pine ``color.new(color, transp)``: transp 0 (opaque) ... 100 (invisible)."""
    rgba = _rgba(color)
    if rgba is None:
        return na
    t = 0 if isna(transp) else max(0.0, min(100.0, float(transp)))
    return _hex(rgba[0], rgba[1], rgba[2], 255 * (100 - t) / 100)


def color_rgb(red, green, blue, transp=0):
    if any(isna(v) for v in (red, green, blue)):
        return na
    t = 0 if isna(transp) else max(0.0, min(100.0, float(transp)))
    return _hex(red, green, blue, 255 * (100 - t) / 100)


def color_from_gradient(value, bottom_value, top_value, bottom_color, top_color):
    lo, hi = _rgba(bottom_color), _rgba(top_color)
    if isna(value) or isna(bottom_value) or isna(top_value) or lo is None or hi is None:
        return na
    span = top_value - bottom_value
    f = 0.0 if span == 0 else max(0.0, min(1.0, (value - bottom_value) / span))
    return _hex(*(a + (b - a) * f for a, b in zip(lo, hi)))


def color_part(color, part: str):
    rgba = _rgba(color)
    if rgba is None:
        return na
    if part == "t":
        return round(100 - rgba[3] * 100 / 255, 2)
    return rgba["rgb".index(part)]


def color_param(value, default: str) -> str:
    """A color parameter from the page: '#rrggbb' / '#rrggbbaa', else the script's default."""
    return value.lower() if _rgba(value) is not None else default


# -- math --------------------------------------------------------------------------------------


def _math1(fn):
    def wrapped(x):
        if isna(x):
            return na
        try:
            return _clean(fn(x))
        except (ValueError, OverflowError, TypeError, ZeroDivisionError):
            return na
    wrapped.__name__ = fn.__name__
    return wrapped


math_abs = _math1(abs)
math_sqrt = _math1(math.sqrt)
math_exp = _math1(math.exp)
math_log = _math1(math.log)
math_log10 = _math1(math.log10)
math_sin, math_cos, math_tan = _math1(math.sin), _math1(math.cos), _math1(math.tan)
math_asin, math_acos, math_atan = _math1(math.asin), _math1(math.acos), _math1(math.atan)
math_todegrees, math_toradians = _math1(math.degrees), _math1(math.radians)
math_floor = _math1(math.floor)
math_ceil = _math1(math.ceil)


def math_sign(x):
    if isna(x):
        return na
    return 1.0 if x > 0 else -1.0 if x < 0 else 0.0


def math_pow(base, exponent):
    if isna(base) or isna(exponent):
        return na
    try:
        result = base ** exponent
    except (OverflowError, ZeroDivisionError, ValueError, TypeError):
        return na
    return na if isinstance(result, complex) else _clean(result)


def math_round(x, precision=None):
    """Pine ``math.round``: nearest value, ties rounding up; with ``precision`` decimals."""
    if isna(x):
        return na
    if precision is None or isna(precision):
        return int(math.floor(x + 0.5))
    scale = 10 ** int(precision)
    return math.floor(x * scale + 0.5) / scale


def math_round_to_mintick(ctx, x):
    if isna(x):
        return na
    tick = ctx.mintick
    return math.floor(x / tick + 0.5) * tick


def math_max(*values):
    if any(isna(v) for v in values):
        return na
    return max(values)


def math_min(*values):
    if any(isna(v) for v in values):
        return na
    return min(values)


def math_avg(*values):
    if not values or any(isna(v) for v in values):
        return na
    return math.fsum(values) / len(values)


# -- ta: helpers -----------------------------------------------------------------------------------


def _values(st, source) -> list:
    """Non-na source values seen at this call site (windows of na-ignoring built-ins)."""
    try:
        vals = st.vals
    except AttributeError:
        vals = st.vals = []
    if not isna(source):
        vals.append(source)
    return vals


def _history(st, source) -> list:
    """Every source value seen at this call site, na included (bar-window built-ins)."""
    try:
        hist = st.hist
    except AttributeError:
        hist = st.hist = []
    hist.append(source)
    return hist


def _window(st, source, length):
    n = _length(length)
    vals = _values(st, source)
    if n == 0 or len(vals) < n:
        return None, n
    return vals[-n:], n


def _bars_window(st, source, length):
    n = _length(length)
    hist = _history(st, source)
    if n == 0 or len(hist) < n:
        return None
    return hist[-n:]


def _prev(st, attr, value):
    """The value stored under ``attr`` on the previous call (na the first time); stores ``value``."""
    old = st.__dict__.get(attr, na)
    setattr(st, attr, value)
    return old


# -- ta: moving averages ----------------------------------------------------------------------------


def ta_sma(st, source, length):
    """Simple moving average of the last ``length`` non-na values."""
    window, n = _window(st, source, length)
    return na if window is None else math.fsum(window) / n


def _smooth(st, source, length, alpha):
    """EMA-style recursion seeded with the SMA of the first ``length`` non-na values."""
    value = st.__dict__.get("value", na)
    if value is na:
        n = _length(length)
        if n == 0:
            return na
        if not isna(source):
            seed = st.__dict__.setdefault("seed", [])
            seed.append(source)
            if len(seed) >= n:
                value = st.value = math.fsum(seed[-n:]) / n
                del st.seed
        return value
    if not isna(source):
        value = st.value = alpha * source + (1 - alpha) * value
    return value


def ta_ema(st, source, length):
    n = _length(length)
    return _smooth(st, source, n, 2.0 / (n + 1) if n else 0.0)


def ta_rma(st, source, length):
    n = _length(length)
    return _smooth(st, source, n, 1.0 / n if n else 0.0)


def ta_wma(st, source, length):
    window, n = _window(st, source, length)
    if window is None:
        return na
    return math.fsum(v * (k + 1) for k, v in enumerate(window)) / (n * (n + 1) / 2)


def ta_vwma(st, source, length):
    volume = st.ctx.volumes[st.ctx.index]
    return div(ta_sma(st.sub("pv"), source * volume, length), ta_sma(st.sub("v"), volume, length))


def ta_hma(st, source, length):
    n = _length(length)
    if n == 0:
        return na
    half = ta_wma(st.sub("half"), source, n // 2) if n >= 2 else na
    full = ta_wma(st.sub("full"), source, n)
    return ta_wma(st.sub("out"), 2 * half - full, int(math.floor(math.sqrt(n))))


def ta_swma(st, source):
    window = _bars_window(st, source, 4)
    if window is None or any(isna(v) for v in window):
        return na
    return window[0] / 6 + window[1] * 2 / 6 + window[2] * 2 / 6 + window[3] / 6


# -- ta: volatility -------------------------------------------------------------------------------


def ta_tr(ctx, handle_na=False):
    """True range; on the first bar it is high - low when ``handle_na`` is true, else na."""
    i = ctx.index
    high, low = ctx.highs[i], ctx.lows[i]
    if i == 0:
        return high - low if handle_na else na
    prev_close = ctx.closes[i - 1]
    return max(high - low, abs(high - prev_close), abs(low - prev_close))


def ta_atr(st, length):
    return ta_rma(st, ta_tr(st.ctx, True), length)


def ta_variance(st, source, length, biased=True):
    window, n = _window(st, source, length)
    if window is None:
        return na
    mean = math.fsum(window) / n
    denom = n if biased else n - 1
    if denom <= 0:
        return na
    return math.fsum((v - mean) * (v - mean) for v in window) / denom


def ta_stdev(st, source, length, biased=True):
    var = ta_variance(st, source, length, biased)
    return na if isna(var) else math.sqrt(max(var, 0.0))


def ta_dev(st, source, length):
    window, n = _window(st, source, length)
    if window is None:
        return na
    mean = math.fsum(window) / n
    return math.fsum(abs(v - mean) for v in window) / n


def ta_bb(st, source, length, mult):
    basis = ta_sma(st.sub("basis"), source, length)
    dev = mult * ta_stdev(st.sub("dev"), source, length)
    return basis, basis + dev, basis - dev


def ta_bbw(st, source, length, mult):
    basis, upper, lower = ta_bb(st, source, length, mult)
    return div((upper - lower) * 100, basis)


def ta_kc(st, source, length, mult, use_true_range=True):
    basis = ta_ema(st.sub("basis"), source, length)
    ctx = st.ctx
    span = ta_tr(ctx, True) if use_true_range else ctx.highs[ctx.index] - ctx.lows[ctx.index]
    rng = ta_ema(st.sub("range"), span, length)
    return basis, basis + rng * mult, basis - rng * mult


# -- ta: oscillators ------------------------------------------------------------------------------


def ta_rsi(st, source, length):
    """Wilder RSI: rma of gains over rma of losses (100 when there are no losses)."""
    prev = _prev(st, "prev", source)
    if isna(source) or isna(prev):
        up = down = na
    else:
        change = source - prev
        up = change if change > 0 else 0.0
        down = -change if change < 0 else 0.0
    avg_up = ta_rma(st.sub("up"), up, length)
    avg_down = ta_rma(st.sub("down"), down, length)
    if isna(avg_up) or isna(avg_down):
        return na
    if avg_down == 0:
        return 100.0
    if avg_up == 0:
        return 0.0
    return 100.0 - 100.0 / (1.0 + avg_up / avg_down)


def ta_macd(st, source, fast_length, slow_length, signal_length):
    fast = ta_ema(st.sub("fast"), source, fast_length)
    slow = ta_ema(st.sub("slow"), source, slow_length)
    line = fast - slow
    signal = ta_ema(st.sub("signal"), line, signal_length)
    return line, signal, line - signal


def ta_stoch(st, source, high, low, length):
    lowest = ta_lowest(st.sub("low"), low, length)
    highest = ta_highest(st.sub("high"), high, length)
    return div(100 * (source - lowest), highest - lowest)


def ta_cci(st, source, length):
    mean = ta_sma(st.sub("mean"), source, length)
    dev = ta_dev(st.sub("dev"), source, length)
    return div(source - mean, 0.015 * dev)


def ta_mfi(st, source, length):
    """Money flow index, as Pine defines it (math.sum of up/down volume * source)."""
    ctx = st.ctx
    volume = ctx.volumes[ctx.index]
    prev = _prev(st, "prev", source)
    change = na if isna(prev) or isna(source) else source - prev
    up = 0.0 if change <= 0.0 else volume * source       # na change counts on both sides, like Pine
    down = 0.0 if change >= 0.0 else volume * source
    upper = math_sum(st.sub("upper"), up, length)
    lower = math_sum(st.sub("lower"), down, length)
    if isna(upper) or isna(lower):
        return na
    if lower == 0:
        return 100.0
    return 100.0 - 100.0 / (1.0 + upper / lower)


def ta_wpr(st, length):
    ctx = st.ctx
    highest = ta_highest(st.sub("high"), ctx.highs[ctx.index], length)
    lowest = ta_lowest(st.sub("low"), ctx.lows[ctx.index], length)
    return div(100 * (ctx.closes[ctx.index] - highest), highest - lowest)


def ta_obv(st):
    ctx = st.ctx
    i = ctx.index
    total = st.__dict__.get("total", 0.0)
    if i > 0:
        change = ctx.closes[i] - ctx.closes[i - 1]
        total += ctx.volumes[i] if change > 0 else -ctx.volumes[i] if change < 0 else 0.0
    st.total = total
    return total


# -- ta: windows -------------------------------------------------------------------------------------


def _extreme(window, pick):
    vals = [v for v in window if not isna(v)]
    return pick(vals) if vals else na


def ta_highest(st, source, length):
    window = _bars_window(st, source, length)
    return na if window is None else _extreme(window, max)


def ta_lowest(st, source, length):
    window = _bars_window(st, source, length)
    return na if window is None else _extreme(window, min)


def _extreme_bars(window, better):
    best, best_k = na, na
    n = len(window)
    for k, v in enumerate(window):          # oldest first; ties go to the most recent bar
        if isna(v):
            continue
        if best is na or better(v, best) or v == best:
            best, best_k = v, k
    return na if best_k is na else -(n - 1 - best_k)


def ta_highestbars(st, source, length):
    window = _bars_window(st, source, length)
    return na if window is None else _extreme_bars(window, lambda a, b: a > b)


def ta_lowestbars(st, source, length):
    window = _bars_window(st, source, length)
    return na if window is None else _extreme_bars(window, lambda a, b: a < b)


def math_sum(st, source, length):
    """Pine ``math.sum`` (sliding sum of the last ``length`` non-na values)."""
    window, n = _window(st, source, length)
    return na if window is None else math.fsum(window)


ta_sum = math_sum


def ta_median(st, source, length):
    window, n = _window(st, source, length)
    return na if window is None else statistics.median(window)


def ta_linreg(st, source, length, offset=0):
    window, n = _window(st, source, length)
    if window is None:
        return na
    if n == 1:
        return window[0]
    xs = range(n)
    mean_x = (n - 1) / 2
    mean_y = math.fsum(window) / n
    sxx = math.fsum((x - mean_x) ** 2 for x in xs)
    sxy = math.fsum((x - mean_x) * (y - mean_y) for x, y in zip(xs, window))
    slope = sxy / sxx
    intercept = mean_y - slope * mean_x
    return intercept + slope * (n - 1 - (0 if isna(offset) else offset))


def ta_change(st, source, length=1):
    k = _offset(length)
    hist = _history(st, source)
    if k is None or len(hist) <= k:
        return na
    prev = hist[-1 - k]
    if isinstance(source, bool) or isinstance(prev, bool):
        return False if isna(source) or isna(prev) else source != prev
    return source - prev


ta_mom = ta_change


def ta_roc(st, source, length):
    k = _offset(length)
    hist = _history(st, source)
    if k is None or k == 0 or len(hist) <= k:
        return na
    prev = hist[-1 - k]
    return div(100 * (source - prev), prev)


def ta_cum(st, source):
    total = st.__dict__.get("total", 0.0)
    if not isna(source):
        total += source
    st.total = total
    return total


def ta_rising(st, source, length):
    k = _length(length)
    hist = _history(st, source)
    if k == 0 or len(hist) <= k or isna(source):
        return False
    previous = hist[-1 - k:-1]
    return all(not isna(v) and source > v for v in previous)


def ta_falling(st, source, length):
    k = _length(length)
    hist = _history(st, source)
    if k == 0 or len(hist) <= k or isna(source):
        return False
    previous = hist[-1 - k:-1]
    return all(not isna(v) and source < v for v in previous)


# -- ta: events ----------------------------------------------------------------------------------------


def ta_crossover(st, a, b) -> bool:
    """True on the bar where ``a`` goes from at or below ``b`` to above it."""
    pa = _prev(st, "a", a)
    pb = _prev(st, "b", b)
    return bool(a > b and pa <= pb)


def ta_crossunder(st, a, b) -> bool:
    pa = _prev(st, "a", a)
    pb = _prev(st, "b", b)
    return bool(a < b and pa >= pb)


def ta_cross(st, a, b) -> bool:
    pa = _prev(st, "a", a)
    pb = _prev(st, "b", b)
    return bool((a > b and pa <= pb) or (a < b and pa >= pb))


def ta_barssince(st, condition):
    count = st.__dict__.get("count", na)
    if condition:
        count = 0
    elif count is not na:
        count += 1
    st.count = count
    return count


def ta_valuewhen(st, condition, source, occurrence=0):
    try:
        seen = st.seen
    except AttributeError:
        seen = st.seen = []
    if condition:
        seen.append(source)
    k = _offset(occurrence)
    if k is None or k >= len(seen):
        return na
    return seen[-1 - k]


def ta_pivothigh(st, source, left, right):
    """The pivot value, reported ``right`` bars after the pivot bar (na elsewhere)."""
    return _pivot(st, source, left, right, high=True)


def ta_pivotlow(st, source, left, right):
    return _pivot(st, source, left, right, high=False)


def _pivot(st, source, left, right, high):
    hist = _history(st, source)
    lb, rb = _offset(left), _offset(right)
    if lb is None or rb is None:
        return na
    span = lb + rb + 1
    if len(hist) < span:
        return na
    candidate = hist[-1 - rb]
    if isna(candidate):
        return na
    left_side = hist[len(hist) - span:len(hist) - 1 - rb]
    right_side = hist[len(hist) - rb:]
    for v in left_side:      # strictly beyond every bar on the left
        if isna(v) or (v >= candidate if high else v <= candidate):
            return na
    for v in right_side:     # at least as far as every bar on the right
        if isna(v) or (v > candidate if high else v < candidate):
            return na
    return candidate


def ta_vwap(st, source, anchor=None, stdev_mult=None):
    """Volume-weighted average of ``source``, reset each session (22:00 UTC) or when ``anchor`` is true."""
    ctx = st.ctx
    i = ctx.index
    if anchor is None:
        key = (ctx.times[i] - SESSION_START_UTC) // 86400
        new = key != st.__dict__.get("key")
        st.key = key
    else:
        new = bool(anchor) or "v" not in st.__dict__
    if new:
        st.pv, st.v, st.pv2 = 0.0, 0.0, 0.0
    volume = ctx.volumes[i]
    if not isna(source):
        st.pv += source * volume
        st.v += volume
        st.pv2 += source * source * volume
    value = st.pv / st.v if st.v > 0 else na
    if stdev_mult is None:
        return value
    if value is na:
        return na, na, na
    dev = math.sqrt(max(st.pv2 / st.v - value * value, 0.0))
    return value, value + stdev_mult * dev, value - stdev_mult * dev


def ta_supertrend(st, factor, atr_period):
    """Pine ``ta.supertrend``: ``[line, direction]``; direction -1 while the line is the lower band."""
    ctx = st.ctx
    i = ctx.index
    atr = ta_atr(st.sub("atr"), atr_period)
    src = ctx.hl2s[i]
    upper = src + factor * atr
    lower = src - factor * atr
    prev_lower = nz(st.__dict__.get("lower", na))
    prev_upper = nz(st.__dict__.get("upper", na))
    prev_close = ctx.closes[i - 1] if i > 0 else na
    if not isna(atr):
        lower = lower if (lower > prev_lower or prev_close < prev_lower) else prev_lower
        upper = upper if (upper < prev_upper or prev_close > prev_upper) else prev_upper
    prev_atr = _prev(st, "atr", atr)
    prev_line = st.__dict__.get("line", na)
    close = ctx.closes[i]
    if isna(atr):
        direction = line = na
    else:
        if isna(prev_atr):
            direction = 1
        elif prev_line == prev_upper:
            direction = -1 if close > upper else 1
        else:
            direction = 1 if close < lower else -1
        line = lower if direction == -1 else upper
    st.lower, st.upper, st.line = lower, upper, line
    return line, direction


def ta_sar(st, start, inc, maximum):
    """Parabolic SAR, following the reference implementation in the Pine manual."""
    ctx = st.ctx
    i = ctx.index
    highs, lows, closes = ctx.highs, ctx.lows, ctx.closes
    d = st.__dict__
    if "result" not in d:
        st.result, st.max_min, st.acc, st.below = na, na, na, na
    result, max_min, acc, below = st.result, st.max_min, st.acc, st.below
    first_trend_bar = False
    if i == 1:
        if closes[1] > closes[0]:
            below, max_min, result = True, highs[1], lows[0]
        else:
            below, max_min, result = False, lows[1], highs[0]
        first_trend_bar = True
        acc = start
    result = result + acc * (max_min - result)
    if below:
        if result > lows[i]:
            first_trend_bar, below = True, False
            result = math_max(highs[i], max_min)
            max_min, acc = lows[i], start
    else:
        if result < highs[i]:
            first_trend_bar, below = True, True
            result = math_min(lows[i], max_min)
            max_min, acc = highs[i], start
    if not first_trend_bar:
        if below:
            if highs[i] > max_min:
                max_min, acc = highs[i], math_min(acc + inc, maximum)
        else:
            if lows[i] < max_min:
                max_min, acc = lows[i], math_min(acc + inc, maximum)
    if below:
        result = math_min(result, lows[i - 1] if i >= 1 else na)
        if i > 1:
            result = math_min(result, lows[i - 2])
    else:
        result = math_max(result, highs[i - 1] if i >= 1 else na)
        if i > 1:
            result = math_max(result, highs[i - 2])
    st.result, st.max_min, st.acc, st.below = result, max_min, acc, below
    return result


def fixnan(st, source):
    """Pine ``fixnan``: the last non-na value seen at this call site."""
    if not isna(source):
        st.last = source
    return st.__dict__.get("last", na)


# -- output ------------------------------------------------------------------------------------------


def _point_value(value):
    if isna(value):
        return None
    try:
        number = float(value)
    except (TypeError, ValueError):
        return None
    return number if math.isfinite(number) else None


class _Out:
    def __init__(self, ctx, kind, id, label, color, offset=0, **style):
        self.ctx = ctx
        self.kind = kind
        self.id = id
        self.label = label
        self.color = color
        self.offset = int(offset or 0)
        self.style = style
        self.points = []

    def _time(self, index):
        j = index + self.offset
        return self.ctx.times[j] if 0 <= j < self.ctx.size else None

    def _color(self, colors):
        """(series color, keep per-point colors?): one color when every point has the same one."""
        distinct = {c for c in colors if c is not None}
        if not distinct:
            return self.color or "#2962ff", False
        if len(distinct) == 1:
            return distinct.pop(), False
        return self.color or next(c for c in colors if c is not None), True


class LineOut(_Out):
    def add(self, value, color=None):
        """One bar's value. An na color hides the point, as it does in Pine."""
        if color is not None and isna(color):
            value = na
            color = None
        self.points.append((self.ctx.index, value, color))

    def export(self) -> dict:
        color, per_point = self._color([c for _, _, c in self.points])
        out = []
        for index, value, c in self.points:
            t = self._time(index)
            v = _point_value(value)
            if t is None or v is None:
                continue
            point = {"time": t, "value": v}
            if per_point and c is not None:
                point["color"] = c
            out.append(point)
        series = {"id": self.id, "label": self.label, "type": self.kind, "color": color, "points": out}
        series.update(self.style)
        return series


class MarkerOut(_Out):
    def __init__(self, ctx, id, label, color, shape="circle", position="aboveBar", text=None, size=None, offset=0):
        super().__init__(ctx, "markers", id, label, color, offset)
        self.shape, self.position, self.text, self.size = shape, position, text, size

    def add(self, when, color=None, text=None, shape=None, position=None):
        """A marker on this bar when ``when`` is true (or a non-zero number)."""
        if isna(when) or not when or (color is not None and isna(color)):
            return
        self.points.append((self.ctx.index, color, text, shape, position))

    def add_arrow(self, value, color_up, color_down):
        """plotarrow: an up arrow below the bar for positive values, a down arrow above for negative."""
        if isna(value) or value == 0:
            return
        if value > 0:
            self.points.append((self.ctx.index, color_up, None, "arrowUp", "belowBar"))
        else:
            self.points.append((self.ctx.index, color_down, None, "arrowDown", "aboveBar"))

    def export(self) -> dict:
        color, _ = self._color([c for _, c, _, _, _ in self.points])
        out = []
        for index, c, text, shape, position in self.points:
            t = self._time(index)
            if t is None:
                continue
            point = {"time": t, "position": position or self.position, "shape": shape or self.shape,
                     "color": c or color}
            label = self.text if text is None else text
            if label is not None and not isna(label) and str(label) != "":
                point["text"] = str(label)
            if self.size is not None:
                point["size"] = self.size
            out.append(point)
        return {"id": self.id, "label": self.label, "type": "markers", "color": color, "points": out}


class Output:
    """Everything the script draws, in the order it was declared."""

    def __init__(self, ctx):
        self.ctx = ctx
        self.series = []

    def line(self, id, label, color=None, line_width=1, line_style="solid", offset=0) -> LineOut:
        out = LineOut(self.ctx, "line", id, label, color, offset, line_width=line_width, line_style=line_style)
        self.series.append(out)
        return out

    def histogram(self, id, label, color=None, offset=0) -> LineOut:
        out = LineOut(self.ctx, "histogram", id, label, color, offset)
        self.series.append(out)
        return out

    def markers(self, id, label, color=None, shape="circle", position="aboveBar", text=None, size=None,
                offset=0) -> MarkerOut:
        out = MarkerOut(self.ctx, id, label, color, shape, position, text, size, offset)
        self.series.append(out)
        return out

    def result(self) -> dict:
        return {"series": [s.export() for s in self.series]}


# -- helpers used by generated code -------------------------------------------------------------


def hist(series, value, offset):
    """History of an expression: remember ``value`` in ``series`` and return the one ``offset`` slots back."""
    series.push(value)
    return series[offset]


def unpack(value, count):
    """``[a, b] = f()``: the tuple itself, or ``count`` na values when the function gave na."""
    if isinstance(value, tuple) and len(value) == count:
        return value
    return (na,) * count


def color_with_alpha(color, alpha_hex):
    """A color parameter picked on the page has no alpha: apply the script's own ('aa' hex digits)."""
    return color + alpha_hex if isinstance(color, str) and len(color) == 7 else color
